#!/usr/bin/env bash
# Checks the bindings' ABI against SDL's headers: builds tools/abi/abi_check.c with the C compiler and tools/abi/odin with Odin
# (both generated by tools/gen), runs them, and diffs what they print: every record's size, alignment and field offsets,
# every enum constant and every macro's value.
#
#   tools/abi/check.sh
#
# Environment: CC (default cc). It needs the libraries in lib/<platform> (tools/build_sdl3.sh or tools/fetch_sdl3_libs.sh)
# for the Odin program to link, though neither program calls SDL.

set -euo pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO"
OUT="build/abi"
mkdir -p "$OUT"
EXE=""
case "$(uname -s)" in MINGW* | MSYS* | CYGWIN*) EXE=.exe ;; esac # Git Bash on Windows

"${CC:-cc}" -w -I upstream/include -o "$OUT/abi_check_c$EXE" tools/abi/abi_check.c
odin build tools/abi/odin -out:"$OUT/abi_check_odin$EXE"
"$OUT/abi_check_c$EXE" | tr -d '\r' >"$OUT/c.txt"
"$OUT/abi_check_odin$EXE" | tr -d '\r' >"$OUT/odin.txt"
if ! diff -u "$OUT/c.txt" "$OUT/odin.txt" >"$OUT/diff.txt"; then
	head -n 60 "$OUT/diff.txt"
	echo "abi: the bindings differ from the C headers ($(grep -c '^[-+][^-+]' "$OUT/diff.txt") lines, see $OUT/diff.txt)" >&2
	exit 1
fi
echo "abi: $(wc -l <"$OUT/c.txt") values match"
